    $kits = $this->scopedKits($request);
    if ($kits->isEmpty()) { return response()->json(['data' => []]); }   // REPLACES the `$byMapping === []` early
                                                                          // return — a fully mapping-less org must
                                                                          // still reach tier 2.
    $byMapping = $this->kitsByMapping($kits);
    // ONE cutoff string, computed once and reused by BOTH tiers so they can never diverge.
    $cutoff = now()->subHours(self::LIVE_CUTOFF_HOURS)->toDateTimeString();

    $rows = [];
    if ($byMapping !== []) {
        try { $rows = OrgLivePositionsQuery::query(['mappings' => array_keys($byMapping), 'cutoff' => $cutoff]); }
        catch (\Throwable $e) { Log::warning(<existing message + args, unchanged>); return response()->json(['data' => []]); }
    }
    // The early return inside catch is what implements "no fallback on a thrown tier-1 read" —
    // no bespoke did-it-throw flag. Mirrors ClarityScoutMapController.php:526-538: the fallback
    // table is on the SAME cluster, so retrying it would re-pay the timeout every 10s poll.

    $data = []; $resolved = [];
    foreach ($rows as $row) {
        $kit = $byMapping[$row['mapping']] ?? null;
        if ($kit === null || $row['lat'] === 0.0 && $row['lng'] === 0.0) { continue; }   // :108 discard UNCHANGED
        $resolved[(int) $kit->id] = true;
        $data[] = $this->driverPositionEntry(
            $kit, $row['lat'], $row['lng'], Carbon::parse($row['timestamp_utc'], 'UTC'),
            $row['speed'] > 1 ? $row['heading'] : null, 'gps',
        );
    }

    // Tier 2 (DEV-2253). Missing set comes from the FULL scoped collection, NOT $byMapping:
    // kitsByMapping() (:742-757) drops kits with a null/empty kit_mapping, and kit_scan_paths
    // is keyed (org_id, kit_id) so it needs no mapping at all.
    $missing = $kits->reject(static fn (Kit $kit) => isset($resolved[(int) $kit->id]))->values();
    if ($missing->isNotEmpty()) {
        try {
            $fallback = OrgScanPathPositionsQuery::query([
                'org_id'  => (int) $user->org_id,
                'kit_ids' => $missing->pluck('id')->map(static fn ($id) => (int) $id)->all(),
                'cutoff'  => $cutoff,
            ]);
            $byId = $missing->keyBy(static fn (Kit $kit) => (int) $kit->id);
            foreach ($fallback as $row) {
                $kit = $byId->get((int) $row['kit_id']);
                if ($kit === null) { continue; }
                $data[] = $this->driverPositionEntry(
                    $kit, $row['lat'], $row['lng'], Carbon::parse($row['timestamp_utc'], 'UTC'), null, 'scan_path',
                );
            }
        } catch (\Throwable $e) {
            // Degrade to tier-1-only. NEVER wipe $data: a fallback failure must not blank
            // the drivers that ARE reporting GPS.
            Log::warning('birds-eye scan-path fallback read failed; returning live positions only', [
                'org_id' => $user->org_id, 'missing_kits' => $missing->count(), 'exception' => $e->getMessage(),
            ]);
        }
    }
    return response()->json(['data' => $data]);

  NEW private helper (place directly under driverPositions(), above driverPaths()):
    /** @return array<string, mixed> */
    private function driverPositionEntry(Kit $kit, float $lat, float $lng, Carbon $scannedAt,
                                        ?float $heading, string $positionSource): array
    {
        return [
            'kit_id' => (int) $kit->id,
            'name' => $kit->name,
            'driver_name' => $kit->settings?->user?->name,
            'lat' => $lat,
            'lng' => $lng,
            'heading' => $heading,
            'scanned_at' => $scannedAt->toIso8601String(),
            'minutes_ago' => (int) abs(now()->diffInMinutes($scannedAt)),
            'vehicle_type' => $kit->settings?->vehicle_type?->value,
            // Unchanged: `source` means scanner-hardware vs browser-GPS and is consumed by
            // stores/map.js:474. Do NOT repurpose it (Q3).
            'source' => 'scan',
            // NEW (DEV-2253): provenance. 'gps' = a live clarity.sc_positions fix;
            // 'scan_path' = a <=15-min-stale clarity.kit_scan_paths last-scan point.
            'position_source' => $positionSource,
        ];
    }
