  Below DRIVER_RED_DOT (:674-682) add a dimmed variant + a provenance-aware icon/title pair:
    // DEV-2253: a scan-derived dot is the driver's LAST SCAN position (up to ~15 min
    // stale, and frozen while they are driving without scanning), not a live GPS fix.
    // Dim it so the fleet board reads honestly; the tooltip says why.
    const SCAN_DERIVED_OPACITY = 0.45;
    function isScanDerived(pos) { return pos?.position_source === 'scan_path'; }
    function driverIcon(vehicleType, scanDerived = false) {
        const icon = (vehicleType ? createVehicleIcon(vehicleType) : null) ?? DRIVER_RED_DOT;
        return scanDerived
            ? { ...icon, fillOpacity: SCAN_DERIVED_OPACITY, strokeOpacity: SCAN_DERIVED_OPACITY }
            : icon;
    }
    function driverTitle(pos) {
        const name = pos.driver_name || pos.name || '';
        return isScanDerived(pos)
            ? `${name} — last scan position (no live GPS)`.trim()
            : name;
    }
